function validate([bits]) {
  if (!Array.isArray(bits) || bits.length < 1 || bits.length > 1000) return 'bits needs 1 to 1000 values.';
  if (bits.some(b => b !== 0 && b !== 1)) return 'Each bit is 0 or 1.';
  if (bits[bits.length - 1] !== 0) return 'The last bit must be 0.';
  return null;
}

