function isOneBitCharacter(bits) {
  // ok[k]: the first k bits split exactly into whole characters.
  // The last 0 stands alone exactly when everything before it splits cleanly.
  const n = bits.length;
  const ok = new Array(n + 1).fill(false);
  ok[0] = true;
  for (let k = 1; k <= n; k++) {
    if (ok[k - 1] && bits[k - 1] === 0) ok[k] = true;
    if (k >= 2 && ok[k - 2] && bits[k - 2] === 1) ok[k] = true;
  }
  return ok[n - 1];
}

generator:
function generate(rand, size) {
  const n = size === 'large' ? 900 + Math.floor(rand() * 101) : 1 + Math.floor(rand() * 8);
  const ones = rand();
  const bits = [];
  for (let i = 0; i < n - 1; i++) bits.push(rand() < ones ? 1 : 0);
  // Sometimes end with a long run of ones so the parity before the final 0 decides the answer.
  if (size === 'large' && rand() < 0.5) {
    const run = Math.floor(rand() * 200);
    for (let i = Math.max(0, n - 1 - run); i < n - 1; i++) bits[i] = 1;
  }
  bits.push(0);
  return [bits];
}
